gameActivityFinalizeConfigRulesAdditions.insert:
// Native Experiences cover GameActivity. Keep the renderer independent of its
// suspended window so Nuxie's scoped game-thread callbacks can complete.
variables.put("EnableNewBackgroundBehavior", "true");

buildGradleAdditions.insert:
def nuxiePins = new groovy.json.JsonSlurper().parse(file("nuxie-native-pins.json"))
repositories {
    maven { url uri("nuxie-maven") }
    google()
    mavenCentral()
}
dependencies {
    implementation files("libs/nuxie-unreal-bridge.aar")
    implementation "ai.nuxie:nuxie-android:0.2.0-${nuxiePins.android.revision}"
    implementation "org.jetbrains.kotlinx:kotlinx-coroutines-android:1.9.0"
}
